import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Claim, cents } from '../claims/claims-api';

/** A percent of 0.00 or more with up to two decimals. */
export const PCT_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

export interface Rate {
  grade: string;
  /** The first date (yyyy-mm-dd) the rate is in force; null when it applies from the beginning of time. */
  from: string | null;
  /** Always with two decimals, as the server formats it. */
  pct: string;
}

/** Of one grade's rates, the one in force on a date (yyyy-mm-dd): the one with the latest from-date
 *  on or before it, an undated rate applying from the beginning of time; null when none applies yet. */
export function pctOn(rates: readonly Rate[], date: string | null): string | null {
  let best: Rate | null = null;
  for (const r of rates) {
    if (r.from !== null && (date === null || r.from > date)) continue;
    if (best === null || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best?.pct ?? null;
}

// The sheet's rate for each grade, read and written through the server.
@Injectable({ providedIn: 'root' })
export class RatesApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Promise<Rate[]> {
    return firstValueFrom(this.http.get<Rate[]>(this.url(sheetId), { headers: this.headers() }));
  }

  set(sheetId: string, grade: string, pct: string, from: string | null): Promise<Rate> {
    return firstValueFrom(
      this.http.put<Rate>(`${this.url(sheetId)}/${encodeURIComponent(grade)}`, { pct, from }, { headers: this.headers() }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function rateError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Choose a grade, enter a percent of 0.00 or more with up to two decimals and a from-date as yyyy-mm-dd or none.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The rate was changed at the same moment; try again.';
  return 'Something went wrong; try again.';
}

/** Whole cents times a percent (in hundredths of a percent), divided by 100, in whole cents,
 *  rounded half to even. Worked in BigInt so large amounts stay exact. */
export function dueCents(cents: number, pctHundredths: number): number {
  const product = BigInt(cents) * BigInt(pctHundredths);
  const whole = product / 10000n;
  const rest = product % 10000n;
  return Number(rest > 5000n || (rest === 5000n && whole % 2n === 1n) ? whole + 1n : whole);
}

/** A claim's due in cents: the due fixed when it was settled, else the due a statement bound it
 *  to, else its amount times its grade's rate in force on its date, rounded half to even; null
 *  (n/a) with no rate in force then. */
export function claimDueCents(rates: readonly Rate[], c: Claim): number | null {
  if (c.settledDue !== null) return cents(c.settledDue);
  if (c.stated) return c.statedDue === null ? null : cents(c.statedDue);
  const pct = pctOn(rates, c.date);
  return pct === null ? null : dueCents(cents(c.amount), cents(pct));
}
import { Component, computed, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { GRADES } from '../people/people-api';
import { PCT_PATTERN, Rate, RatesApi, pctOn, rateError } from './rates-api';

// The rate in force on the sheet's today for each grade, every rate the sheet has for each grade by
// from-date, and the form that sets a grade's rate from a date.
@Component({
  selector: 'app-rates',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Set rate">
        <label for="rate-form-grade">Grade</label>
        <select id="rate-form-grade" data-testid="rate-form-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input id="rate-form-pct" data-testid="rate-form-pct" formControlName="pct" inputmode="decimal" autocomplete="off" />
        <label for="rate-form-from">From (blank: always)</label>
        <input id="rate-form-from" type="date" data-testid="rate-form-from" formControlName="from" />
        <button type="submit" data-testid="rate-form-submit">Set rate</button>
        @if (error(); as err) {
          <p role="alert" data-testid="rate-form-error">{{ err }}</p>
        }
      </form>
      <table data-testid="rates-current">
        <caption>In force today</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">Rate (%)</th></tr>
        </thead>
        <tbody>
          @for (g of grades; track g) {
            <tr>
              <th scope="row">{{ g }}</th>
              <td [attr.data-testid]="'rate-current-' + g">{{ currentOf(g) ?? 'n/a' }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table data-testid="rates-list">
        <caption>All rates</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">From</th><th scope="col">Rate (%)</th></tr>
        </thead>
        <tbody>
          @for (r of sorted(); track r.grade + '-' + (r.from ?? 'start')) {
            <tr [attr.data-testid]="'rate-row-' + r.grade + '-' + (r.from ?? 'start')">
              <th scope="row" data-testid="rate-grade">{{ r.grade }}</th>
              <td data-testid="rate-from">{{ r.from ?? '' }}</td>
              <td data-testid="rate-pct">{{ r.pct }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Rates {
  private readonly session = inject(Session);
  private readonly api = inject(RatesApi);

  /** The sheet's rates, each for a grade from a from-date. */
  readonly rates = input.required<Rate[]>();
  /** The rates by grade, then from-date (an undated rate first). */
  protected readonly sorted = computed(() => [...this.rates()].sort((a, b) =>
    a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? '')));
  /** A rate just set, for the sheet to take in. */
  readonly saved = output<Rate>();

  protected readonly grades = GRADES;
  protected readonly error = signal<string | null>(null);
  /** Whether a submit is waiting for its answer; a second submit meanwhile is ignored. */
  private submitting = false;

  protected readonly form = new FormGroup({
    grade: new FormControl<string>('A', { nonNullable: true }),
    pct: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(null));
  }

  /** The grade's rate in force on the sheet's today, or null when it has none then. */
  protected currentOf(grade: string): string | null {
    return pctOn(this.rates().filter((r) => r.grade === grade), this.session.today());
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const { grade, pct, from } = this.form.getRawValue();
    if (!(GRADES as readonly string[]).includes(grade)) {
      this.error.set('Choose a grade.');
      return;
    }
    const value = pct.trim();
    if (!PCT_PATTERN.test(value)) {
      this.error.set('Enter a percent of 0.00 or more with up to two decimals.');
      return;
    }
    const fromDate = from.trim();
    if (fromDate !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(fromDate)) {
      this.error.set('Enter a from-date as yyyy-mm-dd, or leave it blank.');
      return;
    }
    this.submitting = true;
    try {
      const rate = await this.api.set(sheetId, grade, value, fromDate || null);
      if (this.session.sheetId() === sheetId) this.saved.emit(rate);
      this.form.reset({ grade, pct: '', from: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(rateError(e));
    } finally {
      this.submitting = false;
    }
  }
}
